 <div class="proc-form-grid"><p><strong>Supplier</strong><br><?=e($o['supplier_name'])?></p><p><strong>Destination Warehouse</strong><br><?=e($o['warehouse_name']??'Legacy / not recorded')?></p><p><strong>Receiving Location</strong><br><?=e($o['destination_location_name']??'Legacy / not recorded')?></p><p><strong>Expected date</strong><br><?=e($o['expected_date']?:'Not set')?></p><p><strong>Currency / Total</strong><br><?=e($o['currency'])?> <?=e(number_format((float)$o['total_amount'],2))?></p></div>
