 <?php if(in_array($o['status'],['draft','submitted','approved','billed'],true)):?><form method="post" action="<?= e(appBasePath()) ?>/procurement/<?=$o['purchase_order_id']?>/action" class="proc-actions"><?=csrfField()?><?php if($o['status']==='draft'):?><button class="btn btn-primary" name="action" value="submit">Submit for approval</button><button class="btn btn-secondary" name="action" value="cancel">Cancel draft</button><?php elseif($o['status']==='submitted'&&$can('procurement.orders.approve')):?><button class="btn btn-primary" name="action" value="approve">Approve PO</button><?php elseif($o['status']==='approved'&&$can('procurement.orders.confirm')):?><button class="btn btn-primary" name="action" value="confirm">Confirm PO</button><?php elseif($o['status']==='billed'):?><button class="btn btn-secondary" name="action" value="close">Close PO</button><?php endif;?></form><?php endif;?>
</section>
<?php if($can('procurement.receipts.create')&&in_array($o['status'],['confirmed','partially_received'],true)):?><section class="card"><h2>Receive goods</h2><p>Create a linked draft receipt. An Inventory user must approve and post it before stock or PO quantities change.</p><form method="post" action="<?= e(appBasePath()) ?>/procurement/<?=$o['purchase_order_id']?>/receipts"><?=csrfField()?><div class="proc-form-grid"><?php foreach($o['lines'] as $line):?><label><?=e($line['sku'])?> quantity (maximum <?=e($line['remaining_to_receive'])?>)<input name="quantity[<?=$line['purchase_order_line_id']?>]" type="number" min="0" max="<?=e($line['remaining_to_receive'])?>" step="0.001" value="0"></label><?php endforeach;?></div><button class="btn btn-primary">Create draft receipt</button></form></section><?php endif;?>
<?php if($can('procurement.returns.post')&&in_array($o['status'],['partially_received','received','partially_billed','billed'],true)):?><section class="card"><h2>Return goods to supplier</h2><p>Only received, unbilled quantities can be returned. Posting moves Stock → Vendor immediately and is idempotent.</p><form method="post" action="<?= e(appBasePath()) ?>/procurement/<?=$o['purchase_order_id']?>/returns"><?=csrfField()?><input type="hidden" name="idempotency_key" value="<?=e(bin2hex(random_bytes(16)))?>"><div class="proc-form-grid"><?php foreach($o['lines'] as $line):$max=max(0,(float)$line['received_quantity']-(float)$line['returned_quantity']-(float)$line['billed_quantity']);?><label><?=e($line['sku'])?> return quantity (maximum <?=e($max)?>)<input name="quantity[<?=$line['purchase_order_line_id']?>]" type="number" min="0" max="<?=e($max)?>" step="0.001" value="0"></label><?php endforeach;?><label class="wide">Reason *<textarea name="reason" minlength="3" required></textarea></label></div><button class="btn btn-primary">Post vendor return</button></form></section><?php endif;?>
