_date" type="date"></label><label class="wide">Destination warehouse *<select name="warehouse_id" required><option value="">Select warehouse</option><?php foreach($data['warehouses'] as $w):?><option value="<?=$w['warehouse_id']?>"><?=e($w['code'].' — '.$w['name'])?></option><?php endforeach;?></select></label><label class="wide">Business justification *<textarea name="justification" required maxlength="1000"></textarea></label></div><h3>Items</h3><div class="proc-line"><label>Product *<select name="product_id[]" required><option value="">Select product</option><?php foreach($data['products'] as $p):?><option value="<?=$p['product_id']?>"><?=e($p['sku'].' — '.$p['name'])?></option><?php endforeach;?></select></label><label>Description *<input name="description[]" required></label><label>Quantity *<input name="quantity[]" type="number" min="0.001" step="0.001" required></label><label>Est. unit price<input name="unit_price[]" type="number" min="0" step="0.0001" value="0"></label><input name="tax_rate[]" type="hidden" value="0"></div><button class="btn btn-primary">Create draft requisition</button></form></section><?php endif;?></div><?php endif;?>

