<script>document.querySelectorAll('select[name="warehouse_id"]').forEach(function(warehouse){var form=warehouse.closest('form');if(!form)return;var location=form.querySelector('select[name="destination_location_id"]');if(!location)return;var filter=function(){Array.from(location.options).forEach(function(option,index){if(index===0)return;option.hidden=option.dataset.warehouse!==warehouse.value;});if(location.selectedOptions[0]&&location.selectedOptions[0].hidden)location.value='';};warehouse.addEventListener('change',filter);filter();});</script>

<?php if(in_array($section,['receipts','returns'],true)):?><section class="card"><h2><?=e($sections[$section])?></h2><?php $rows=$section==='returns'?($data['returns']??[]):array_merge(...array_map(static fn($o)=>[],$orders)); if($section==='returns'&&$rows):?><div class="table-responsive"><table class="data-table"><thead><tr><th>Return</th><th>PO</th><th>Supplier</th><th>Date</th><th>Status</th><th>Reason</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['return_number'])?></td><td><a href="<?= e(appBasePath()) ?>/procurement/<?=$r['purchase_order_id']?>"><?=e($r['po_number'])?></a></td><td><?=e($r['supplier_name'])?></td><td><?=e($r['return_date'])?></td><td><span class="<?=$statusClass($r['status'])?>"><?=e($r['status'])?></span></td><td><?=e($r['reason'])?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="proc-empty"><?=$section==='receipts'?'Open a purchase order to create or follow linked Inventory receipts.':'No vendor returns posted.'?></div><?php endif;?></section><?php endif;?>

<?php if(in_array($section,['bills','payments'],true)):?><section class="card"><h2><?=e($sections[$section])?></h2><?php if(!$bills):?><div class="proc-empty">No supplier bills yet.</div><?php else:?><div class="table-responsive"><table class="data-table"><thead><tr><th>Bill</th><th>PO</th><th>Supplier</th><th>Status</th><th>Payment</th><th>Total</th><th>Outstanding</th><th>Action</th></tr></thead><tbody><?php foreach($bills as $b):?><tr><td><?=e($b['invoice_number'])?></td><td><a href="<?= e(appBasePath()) ?>/procurement/<?=$b['purchase_order_id']?>"><?=e($b['po_number'])?></a></td><td><?=e($b['supplier_name'])?></td><td><span class="<?=$statusClass($b['status'])?>"><?=e($b['status'])?></span></td><td><span class="<?=$statusClass($b['payment_status'])?>"><?=e($b['payment_status'])?></span></td><td><?=e($b['currency'].' '.number_format((float)$b['total_amount'],2))?></td><td><?=e(number_format((float)$b['residual_amount'],2))?></td><td><?php if($b['status']==='draft'&&$can('procurement.bills.post')):?><form method="post" action="<?= e(appBasePath()) ?>/procurement/bills/<?=$b['invoice_id']?>/post"><?=csrfField()?><button class="btn btn-primary">Post bill</button></form><?php elseif($b['status']==='posted'&&$section==='payments'&&$can('procurement.payments.post')&&(float)$b['residual_amount']>0):?><form method="post" action="<?= e(appBasePath()) ?>/procurement/bills/<?=$b['invoice_id']?>/payments" class="proc-actions"><?=csrfField()?><input type="hidden" name="idempotency_key" value="<?=e(bin2hex(random_bytes(16)))?>"><label>Amount<input name="amount" type="number" min="0.01" max="<?=e($b['residual_amount'])?>" step="0.01" required></label><label>Payment date<input name="payment_date" type="date" value="<?=date('Y-m-d')?>" required></label><label>Method<input name="method" value="bank_transfer" required></label><label>Cash / bank journal<select name="journal_id" required><option value="">Select journal</option><?php foreach($data['payment_journals'] as $j):?><option value="<?=$j['journal_id']?>"><?=e($j['journal_name'].' — '.$j['journal_type'])?></option><?php endforeach;?></select></label><button class="btn btn-primary">Post payment</button></form><?php elseif($b['status']==='posted'&&$can('procurement.bills.reverse')&&(float)$b['residual_amount']===(float)$b['total_amount']):?><form method="post" action="<?= e(appBasePath()) ?>/procurement/bills/<?=$b['invoice_id']?>/reverse"><?=csrfField()?><button class="btn btn-secondary">Reverse unpaid bill</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php endif;?>
<?php endif;?>
</div>
